\label{rem:06J3}
We note from \cite[Tag~06J3]{Stacks} that if $\mathcal{D}$ satisfies (RS)
and $A_2\rightarrow A$ is surjective, then any commutative square
completing \eqref{eq:empty square} and lying over \eqref{eq:full square}
is a fibre square.

\label{2.2} 
Let $X$ be a Calabi-Yau threefold with canonical
singularities, and $X_n/A_n$ a deformation of $X$. There is a commutative diagram
\[
\xymatrix@C=30pt
{
T^1(X_n/A_n)\ar[r]^{F}\ar[d]&T^1_{\mathrm{loc}}(X_n/A_n)\ar[d]\\
T^1(X_{n-1}/A_{n-1})\ar[r]^{F}\ar[d]_{\delta}
&T^1_{\mathrm{loc}}(X_{n-1}/A_{n-1}) \ar[d]^{\delta_{\mathrm{loc}}}
\\
T^2\ar[r]_{l}&T^2_{\mathrm{loc}}
}
\]
where
$l|_{\operatorname{im}(\delta)}:\operatorname{im}(\delta)\rightarrow T^2_{\mathrm{loc}}$ is injective.

\label{2.4} 
There are isomorphisms
\begin{itemize}
\item[(a)] $\operatorname{Ext}^1_{\mathcal{O}_{X_n}}(\Omega^1_{X_n/A_n},\mathcal{O}_{\hat X_m})
\cong T^1_{\mathrm{loc}}(X_m/A_m)$ for $m<n$. 
\item[(b)] $\operatorname{Ext}^2_{\mathcal{O}_{X_n}}(\Omega^1_{X_n/A_n}, \mathcal{O}_{\hat X}) = T^2_{\mathrm{loc}}.$
\item[(c)] ${(T^2_{\mathrm{loc}})}^{\scriptscriptstyle \vee}\cong H^1_Z(\Omega^1_X)$, ${(T^2)}^{\scriptscriptstyle \vee}
\cong H^1(\Omega^1_X)$, and the natural map $H^1_Z(\Omega^1_X)\rightarrow
H^1(\Omega^1_X)$ is dual to $l$.
\end{itemize}

\label{5.2} 
Let $\pi:\tilde X\rightarrow X$ be a primitive type II
contraction. Then if $X$ has a non-hypersurface singularity, the exceptional
divisor $E$ of $\pi$ is either
\begin{itemize}
\item[(i)] a normal rational del Pezzo surface of degree $\le 9$ or
\item[(ii)] a nonnormal del Pezzo surface of degree 7.
\end{itemize}

\label{5.8} 
Let $\pi:\tilde X\rightarrow X$ be a primitive type II
contraction with exceptional divisor $E$. Then $X$ is smoothable unless 
\begin{itemize}
\item[(1)] $E\cong\mathbb{P}^2$ or
\item[(2)] $E\cong F_1$. 
\end{itemize}
